import{_ as o,l as s,o as e,c as l,v as t,p as n,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"空间索引","description":"","frontmatter":{"title":"空间索引","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/spatial-index-db.md","filePath":"cs/spatial-index-db.md","lastUpdated":1789023840000}'),h={name:"cs/spatial-index-db.md"};function m(E,a,_,A,u,B){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="空间索引" tabindex="-1">空间索引 <a class="header-anchor" href="#空间索引" aria-label="Permalink to &quot;空间索引&quot;">​</a></h1><div class="epigraph"><p>矩形不能按一维键排序还不拆语义；R 树用最小外接矩形分层，查询是递归裁剪，不是 B+ 的全序下降。</p><footer>—— 据 Guttman, R-Trees, SIGMOD 1984；计算机栏 R 树课接到库；SQL/MM</footer></div><p><a href="/cs/inverted-index-fulltext">上一课</a>的键是词项。本课不建 posting。缺口是几何：点、线、多边形上的相交、包含、kNN。计算机课已有 <a href="/cs/r-tree">R 树</a>；数据库进阶接到 GiST、页、事务与选择率。B+ 只能给 Hilbert 码之类的一维代理，邻接会碎。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>谓词 <code>ST_Intersects(geom, :box)</code> 选择率与 min/max 一维直方图对不上。R 树：叶存几何或 RID+MBR，内部节点 MBR 覆盖孩子。查询从根裁掉与查询窗不相交的枝。缺口是<strong>引擎</strong>：页裂变算法（Guttman、R*）、并发 latch、更新导致 MBR 上提、vacuum。</p><p>网格、quadtree、地理哈希是另一族：规则划分，倾斜时空节点或热点格子。本课以 R 树为主，点名网格。</p><p><span class="marginnote">Guttman SIGMOD 1984。PostgreSQL GiST 把 R 树当扩展。本课不重推分裂启发式，只钉：空间谓词要空间访问路径。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>创建 GiST/SP-GiST/R 树索引于几何列。计划：与 B+ 并列的扫描类型。过滤+精炼：索引用 MBR 粗滤，再精确几何算法（计算几何），避免只信矩形。</p><p>并行：按 R 树子枝或空间分区切工人。zone map 对 MBR 也可以，粒度粗。</p>',10)),(e(),n(c,null,{default:r(()=>[p(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20WIN%5B%22%E6%9F%A5%E8%AF%A2%E7%AA%97%E5%8F%A3%22%5D%20--%3E%20MBR%5B%22%E5%86%85%E9%83%A8%20MBR%20%E8%A3%81%E5%89%AA%22%5D%0A%20%20MBR%20--%3E%20LEAF%5B%22%E5%8F%B6%E5%80%99%E9%80%89%22%5D%0A%20%20LEAF%20--%3E%20EXACT%5B%22%E7%B2%BE%E7%A1%AE%E5%87%A0%E4%BD%95%E8%B0%93%E8%AF%8D%22%5D%0A%20%20EXACT%20--%3E%20ROW%5B%22%E5%9B%9E%E8%A1%A8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>代价：优化器常缺好的空间直方图，易误判「索引扫 vs 全表」。这是基数误差课的空间版。更新：物体移动等于删+插，MBR 调整可能级联。</p><p>与分片：空间分片键难选，热点城市会打爆一 shard——分布式后课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲学习索引。也不把轨迹时序当纯空间；时序库后课。三维、路网最短路是另一索引（CALT 等），点名。</p><p>后课默认：空间谓词走 R 树/GiST 粗滤再精炼。学习索引：用模型代替树下降估位置，有序键上的另一赌局。</p><p>MBR 假阳性靠精炼消化；没有精炼会错结果。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>空间查询用 R 树等 MBR 分层裁剪，再精确几何。</li><li>选择率难估；移动更新贵。</li><li>学习索引下一课：有序键上的模型定位。</li><li>出处：Guttman 1984；GiST；SQL/MM。</li></ul>',9))])}const S=o(h,[["render",m]]);export{T as __pageData,S as default};
